/// <reference path="../pb_data/types.d.ts" />

/**
 * Метка очереди для записей, оставшихся без неё.
 *
 * Запись без seq не доезжает ни до кого: забирают изменения фильтром
 * `seq > отметки`, а сравнение с пустым значением ложно всегда. Такие строки
 * лежат на сервере и не видны никому, причём навсегда — метку ставит хук на
 * запись, а трогать их больше некому.
 *
 * Появились они в час, когда соседний обработчик не дал загрузиться скриптам
 * целиком, и вместе с ним молчал seq.pb.js. Сообщения того часа сохранились,
 * но доставки не получили.
 *
 * Правим прямым запросом, а не сохранением записи: сохранение подняло бы
 * seq.pb.js, и он выдал бы всем строкам одно значение — часы одного мгновения.
 * Одинаковые метки рвут постраничную загрузку: курсор встаёт на этом значении,
 * и остаток страницы под условие «строго больше» уже не попадает.
 *
 * Нумеруем подряд от текущего максимума в порядке авторской отметки — так
 * восстановится и порядок сообщений, и они окажутся новее любой отметки,
 * сохранённой на устройствах.
 *
 * Осторожность ниже — не суеверие: файл в этой папке, который движок не смог
 * разобрать, унёс с собой все соседние, и обмен встал у всех. Поэтому здесь
 * нет ни одной конструкции сложнее тех, что уже работают в seq.pb.js,
 * обработчик не регистрируется, если движку он незнаком, а сама починка живёт
 * внутри try — сервер должен подняться в любом случае.
 */

if (typeof onBootstrap === 'function') {
  onBootstrap((e) => {
    // Приложение поднимаем первым: починка — дело десятое.
    e.next()

    try {
      // Строку запроса принимает только DynamicModel: обычный объект движок
      // не разбирает и падает с «must be a NullStringMap». Ошибка была тихой —
      // её глушил try ниже, и починка молча не делалась ни разу.
      const found = new DynamicModel({ n: 0 })
      e.app
        .db()
        .newQuery('SELECT COUNT(*) AS n FROM records WHERE seq IS NULL OR seq = 0')
        .one(found)

      if (!found.n) return

      e.app
        .db()
        .newQuery(
          'UPDATE records SET seq = (SELECT COALESCE(MAX(seq), 0) FROM records) + (' +
            'SELECT rn FROM (' +
            'SELECT id, ROW_NUMBER() OVER (ORDER BY updated) AS rn FROM records ' +
            'WHERE seq IS NULL OR seq = 0' +
            ') AS t WHERE t.id = records.id' +
            ') WHERE seq IS NULL OR seq = 0',
        )
        .execute()

      console.log('seq: метка проставлена записям без неё — ' + found.n)
      return
    } catch (err) {
      // Обмен работает и без починки, просто без этих строк. Останавливать
      // из-за неё запуск сервера незачем.
      console.log('seq: починку выполнить не удалось — ' + err)
    }
  })
}
